import subprocess, re, os, json

REPO='/app'
# exact validation per spec
FULL = re.compile(r'^prod_[a-z0-9_]{21}_key$')
# loose finder for candidates
LOOSE = re.compile(rb'prod_[A-Za-z0-9_]*_key')
PWKEY = re.compile(rb'"([^"]*[Pp][Aa][Ss][Ss][Ww][Oo][Rr][Dd][^"]*)"\s*:\s*"((?:[^"\\]|\\.)*)"', re.S)

def run(*a):
    try:
        return subprocess.run(a, cwd=REPO, capture_output=True, timeout=30)
    except Exception as e:
        return None

print("== 1. all objects ==")
r = run('git','cat-file','--batch-all-objects','--batch-check')
objs=[]
if r and r.returncode==0:
    for line in r.stdout.decode(errors='replace').splitlines():
        print(line)
        objs.append(line.split()[0])
else:
    print("batch-all failed", r.stderr if r else None)

cands=set()
print("== 2. decompress each object, search ==")
for o in objs:
    r = run('git','cat-file','-p',o)
    if not r or r.returncode!=0: continue
    data=r.stdout
    for m in LOOSE.finditer(data):
        s=m.group().decode()
        print(f"obj {o}: loose candidate {s!r} len={len(s)} fullmatch={bool(FULL.match(s))}")
        if FULL.match(s) and len(s)==32: cands.add(s)
    for m in PWKEY.finditer(data):
        k,v=m.group(1).decode(errors='replace'),m.group(2).decode(errors='replace')
        print(f"obj {o}: pwkey {k!r} -> {v!r} len={len(v)} match={bool(FULL.match(v))}")
        if FULL.match(v) and len(v)==32: cands.add(v)

print("== 3. binary scan all files under .git ==")
for root,dirs,files in os.walk(os.path.join(REPO,'.git')):
    for f in files:
        p=os.path.join(root,f)
        try:
            with open(p,'rb') as fh: data=fh.read()
        except Exception as e:
            print(p,'unreadable',e); continue
        for m in LOOSE.finditer(data):
            s=m.group().decode()
            print(f"file {p}: {s!r} len={len(s)} match={bool(FULL.match(s))}")
            if FULL.match(s) and len(s)==32: cands.add(s)

print("== 4. resolve refs ==")
for ref in ['ORIG_HEAD','c2770bc0d5a9809bf115b4cd1a256fe5810ab4cc','HEAD','master']:
    r=run('git','cat-file','-t',ref)
    out=(r.stdout.decode().strip() if r and r.stdout else '')+' | '+(r.stderr.decode().strip() if r and r.stderr else '')
    print(ref,'->',out)

print("== 5. try show lost files ==")
for c in ['c2770bc0d5a9809bf115b4cd1a256fe5810ab4cc','b69c57c88951c080c8dca875286ec61b193617c2']:
    for what in [c, c+':db_config.json']:
        r=run('git','cat-file','-p',what)
        ok = r.returncode==0 if r else False
        print(what, 'OK' if ok else 'MISSING')

print("== CANDIDATES ==", cands)
with open('/tmp/cands.txt','w') as fh:
    for c in sorted(cands): fh.write(c+'\n')
EOF
